 listen(root,'keydown',e=>{if(e.isComposing||composing)return;if(e.key!=='Escape')dismissedRange=null;if(e.altKey&&['ArrowUp','ArrowDown'].includes(e.key)&&e.target.matches('[data-block-handle]')){e.preventDefault();const id=e.target.dataset.blockHandle,index=doc().blocks.findIndex(b=>b.id===id),target=doc().blocks[index+(e.key==='ArrowDown'?1:-1)];if(target){reorder(id,target.id,e.key==='ArrowDown');root.querySelector('[data-block-handle=\"'+id+'\"]')?.focus();}return;}if(e.target.matches('[data-document-tail]')&&['Enter',' '].includes(e.key)){e.preventDefault();appendAtBottom();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();undo(true);return;}if(menu&&!menu.panel){if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();menu.index=(menu.index+(e.key==='ArrowDown'?1:-1)+menu.items.length)%Math.max(1,menu.items.length);s.popup.querySelectorAll('button').forEach((b,i)=>b.classList.toggle('is-active',i===menu.index));s.popup.querySelector('.is-active')?.scrollIntoView({block:'nearest'});return;}if(e.key==='Enter'){e.preventDefault();const item=menu.items[menu.index];closeMenu();item?.run();return;}if(e.key==='Escape'){e.preventDefault();closeMenu(true);return;}}
 const el=e.target.closest('[data-editable]');if(!el)return;if((e.ctrlKey||e.metaKey)&&['b','i','u'].includes(e.key.toLowerCase())){e.preventDefault();const selection=getSelection();if(selection.rangeCount){savedRange=selection.getRangeAt(0).cloneRange();format(({b:'bold',i:'italic',u:'underline'})[e.key.toLowerCase()]);}return;}if(e.key==='Enter'&&!e.shiftKey&&find(el.dataset.editable).type!=='code'){e.preventDefault();split(el);}else if(e.key==='Backspace'&&merge(el))e.preventDefault();else if(e.key==='Tab'){e.preventDefault();record();const b=find(el.dataset.editable);b.indent=Math.max(0,Math.min(3,(b.indent||0)+(e.shiftKey?-1:1)));changed();draw();focus(b.id);}});
 listen(document,'keydown',e=>{if(e.key==='Escape'&&e.defaultPrevented)return;if(e.key==='Escape'&&s.bubble&&!menu){e.preventDefault();clearTimeout(s.selectionTimer);dismissedRange=savedRange?.cloneRange();const source=(savedRange?.startContainer.nodeType===1?savedRange.startContainer:savedRange?.startContainer.parentElement)?.closest('[data-editable]');closeBubble();source?.focus({preventScroll:true});return;}if(menu?.panel&&!s.popup?.contains(e.target)){if(e.key==='Escape'){e.preventDefault();closeMenu(true);}else if(e.key==='ArrowDown'){e.preventDefault();s.popup?.querySelector('button')?.focus();}return;}if(!menu||menu.panel||root.contains(e.target))return;if(e.key==='Escape'){e.preventDefault();closeMenu(true);}else if(['ArrowDown','ArrowUp','Enter'].includes(e.key)){e.preventDefault();if(e.key==='Enter'){const item=menu.items[menu.index];closeMenu();item?.run();}else{menu.index=(menu.index+(e.key==='ArrowDown'?1:-1)+menu.items.length)%Math.max(1,menu.items.length);s.popup.querySelectorAll('button').forEach((b,i)=>b.classList.toggle('is-active',i===menu.index));}}});
 listen(document,'selectionchange',()=>{clearTimeout(s.selectionTimer);s.selectionTimer=setTimeout(selectionMenu,80);});listen(document,'pointerdown',e=>{if(s.popup?.contains(e.target)||s.bubble?.contains(e.target))return;if(menu)closeMenu();if(!e.target.closest('[data-editable]'))dismissedRange=savedRange?.cloneRange();closeBubble();});
 function dropTarget(x,y){const row=document.elementFromPoint(x,y)?.closest('[data-block]');root.querySelectorAll('.drop-before,.drop-after').forEach(n=>n.classList.remove('drop-before','drop-after'));if(!row||!root.contains(row))return null;const after=y>row.getBoundingClientRect().top+row.getBoundingClientRect().height/2;row.classList.add(after?'drop-after':'drop-before');return {id:row.dataset.block,after};}
 listen(root,'pointerdown',e=>{dismissedRange=null;const handle=e.target.closest('[data-block-handle]');if(handle)handle.draggable=e.pointerType!=='touch';});
 listen(root,'dragstart',e=>{const handle=e.target.closest('[data-block-handle]');if(!handle)return;e.stopPropagation();closeMenu();drag={id:handle.dataset.blockHandle};e.dataTransfer.setData('text/plain',drag.id);e.dataTransfer.effectAllowed='move';handle.closest('[data-block]').classList.add('is-dragging');});listen(root,'dragover',e=>{if(!drag){e.preventDefault();return;}e.preventDefault();drag.target=dropTarget(e.clientX,e.clientY);});listen(root,'drop',e=>{if(!drag){e.preventDefault();const el=e.target.closest('[data-editable]'),text=e.dataTransfer?.getData('text/plain');if(el&&text){record();el.focus();const range=document.caretRangeFromPoint?.(e.clientX,e.clientY);if(range&&el.contains(range.startContainer)){getSelection().removeAllRanges();getSelection().addRange(range);}suppress=true;document.execCommand('insertText',false,text);suppress=false;sync(el);}return;}e.preventDefault();const current=drag;drag=null;if(current.target&&current.target.id!==current.id)reorder(current.id,current.target.id,current.target.after);else draw();});listen(root,'dragend',()=>{if(drag){drag=null;draw();}});
 listen(root,'touchstart',e=>{const handle=e.target.closest('[data-block-handle]');if(!handle||e.touches.length!==1)return;handle.draggable=false;const point=e.touches[0];touch={id:handle.dataset.blockHandle,x:point.clientX,y:point.clientY,active:false};touch.timer=setTimeout(()=>{if(!touch)return;touch.active=true;handle.closest('[data-block]').classList.add('is-dragging');s.suppressClick=true;closeMenu();},400);},{passive:true});
 listen(root,'touchmove',e=>{if(!touch||e.touches.length!==1)return;const point=e.touches[0];if(!touch.active){if(Math.hypot(point.clientX-touch.x,point.clientY-touch.y)>8){clearTimeout(touch.timer);touch=null;}return;}e.preventDefault();touch.target=dropTarget(point.clientX,point.clientY);const scroller=root.closest('.main')||document.scrollingElement;if(point.clientY<80)scroller.scrollBy(0,-12);else if(point.clientY>innerHeight-80)scroller.scrollBy(0,12);},{passive:false});
 const endTouch=(e,cancel=false)=>{if(!touch)return;clearTimeout(touch.timer);const current=touch;touch=null;if(current.active){e.preventDefault();if(!cancel&&current.target&&current.target.id!==current.id)reorder(current.id,current.target.id,current.target.after);else draw();setTimeout(()=>{s.suppressClick=false;},400);}};listen(root,'touchend',e=>endTouch(e),{passive:false});listen(root,'touchcancel',e=>endTouch(e,true),{passive:false});
 listen(root,'load',()=>alignBlockControls(),{capture:true});listen(document,'scroll',repositionSelectionMenu,{capture:true,passive:true});listen(window,'resize',()=>{closeMenu();repositionSelectionMenu();alignBlockControls();});s.controller.signal.addEventListener('abort',()=>{clearTimeout(touch?.timer);clearTimeout(s.selectionTimer);});draw();if(s.dirty&&!s.saving){clearTimeout(s.timer);s.timer=setTimeout(persist,600);}
